import java.util.*;
class LSM {record Entry(int key,Integer value,int sequence){}record Run(List<Entry>entries,Set<Integer>bits){}int limit,sequence;Map<Integer,Entry>mem=new HashMap<>();List<Run>runs=new ArrayList<>();LSM(int limit){this.limit=limit;}
static int hash(String text){int h=(int)2166136261L;for(char ch:text.toCharArray())h=(h^ch)*16777619;h=(h^(h>>>16))*0x85ebca6b;h=(h^(h>>>13))*0xc2b2ae35;return h^(h>>>16);}static int[] bits(int key){return new int[]{hash("a:"+key)&63,hash("b:"+key)&63};}
Run make(Collection<Entry>entries){List<Entry>rows=new ArrayList<>(entries);rows.sort(Comparator.comparingInt(Entry::key));Set<Integer>filter=new HashSet<>();for(Entry e:rows)for(int bit:bits(e.key()))filter.add(bit);return new Run(rows,filter);}
void put(int key,Integer value){mem.put(key,new Entry(key,value,++sequence));if(mem.size()>=limit)flush();}void delete(int key){put(key,null);}void flush(){if(!mem.isEmpty()){runs.add(0,make(mem.values()));mem.clear();}}
void compact(boolean full){if(runs.size()<2)return;int start=full?0:runs.size()-2;List<Run>selected=new ArrayList<>(runs.subList(start,runs.size()));runs.subList(start,runs.size()).clear();Map<Integer,Entry>merged=new HashMap<>();for(Run r:selected)for(Entry e:r.entries())if(!merged.containsKey(e.key())||merged.get(e.key()).sequence()<e.sequence())merged.put(e.key(),e);List<Entry>entries=merged.values().stream().filter(e->!full||e.value()!=null).toList();if(!entries.isEmpty())runs.add(start,make(entries));}
Integer get(int key,boolean bloom){if(mem.containsKey(key))return mem.get(key).value();for(Run r:runs){if(bloom&&(!r.bits().contains(bits(key)[0])||!r.bits().contains(bits(key)[1])))continue;int lo=0,hi=r.entries().size();while(lo<hi){int mid=(lo+hi)/2;if(r.entries().get(mid).key()<key)lo=mid+1;else hi=mid;}if(lo<r.entries().size()&&r.entries().get(lo).key()==key)return r.entries().get(lo).value();}return null;}}
// Read newest runs first; tombstones stop a lookup and mask older data.
